tests.setup:
_r = np.random.default_rng(11)
X = _r.normal(size=(6, 4)); Y = np.array([0, 2, 1, 2, 0, 1])
P = {'W1': _r.normal(size=(4, 5)) * 0.7, 'b1': _r.normal(size=5) * 0.1, 'W2': _r.normal(size=(5, 3)) * 0.7, 'b2': _r.normal(size=3) * 0.1}
def _loss(Q):
    z = np.tanh(X @ Q['W1'] + Q['b1']) @ Q['W2'] + Q['b2']
    z = z - z.max(axis=1, keepdims=True)
    return float(np.mean(np.log(np.exp(z).sum(axis=1)) - z[np.arange(len(Y)), Y]))
def _cd(k, e=1e-6):
    g = np.zeros_like(P[k])
    for i in np.ndindex(g.shape):
        A = {n: v.copy() for n, v in P.items()}; A[k][i] += e
        Bq = {n: v.copy() for n, v in P.items()}; Bq[k][i] -= e
        g[i] = (_loss(A) - _loss(Bq)) / (2 * e)
    return g
def _rel(k):
    a, n = mlp_backward(X, P, Y)[k], _cd(k)
    return bool(np.abs(a - n).max() / max(np.abs(n).max(), 1e-12) < 1e-6)

