def _l2(p, g, lr, wd, b1=0.9, b2=0.999, eps=1e-8):
    g = g + wd * p
    m = (1 - b1) * g / (1 - b1); v = (1 - b2) * g * g / (1 - b2)
    return p - lr * m / (np.sqrt(v) + eps)
